import path from 'node:path';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { runNpmAuditJson } from '../../npmSecurityAudit.js';
import securityAuditPlugin, { resetAuditCache, } from '../../plugins/securityAuditPlugin.js';
vi.mock('../../npmSecurityAudit.ts', () => ({
    runNpmAuditJson: vi.fn(),
}));
function createPlugin(auditRoot, extensionLabel = 'SomeFile.js') {
    const logger = {
        info: vi.fn(),
        error: vi.fn(),
        debug: vi.fn(),
        warn: vi.fn(),
    };
    const plugin = securityAuditPlugin({
        logger,
        auditRoot,
        extensionLabel,
    });
    return { logger, plugin };
}
function createRollupContext() {
    return {
        emitFile: vi.fn(),
    };
}
async function runGenerateBundle(plugin, ctx) {
    const hook = plugin.generateBundle;
    const fn = typeof hook === 'function' ? hook : hook.handler;
    await fn.call(ctx, {}, {}, false);
}
describe('securityAuditPlugin', () => {
    beforeEach(() => {
        vi.mocked(runNpmAuditJson).mockReset();
        resetAuditCache();
    });
    it('skips emit when runNpmAuditJson is skipped', async () => {
        vi.mocked(runNpmAuditJson).mockResolvedValue({
            source: '',
            exitCode: 0,
            skipped: true,
        });
        const { logger, plugin } = createPlugin('/tmp/ext');
        const ctx = createRollupContext();
        await runGenerateBundle(plugin, ctx);
        expect(ctx.emitFile).not.toHaveBeenCalled();
        expect(logger.debug).toHaveBeenCalledWith(expect.stringContaining('Skipping npm audit'));
    });
    it('logs info and emits asset on clean audit (exit code 0)', async () => {
        const source = '{"metadata":{"vulnerabilities":{"total":0}}}';
        vi.mocked(runNpmAuditJson).mockResolvedValue({
            source,
            exitCode: 0,
            skipped: false,
        });
        const { logger, plugin } = createPlugin(path.join('app', 'extensions', 'cards'));
        const ctx = createRollupContext();
        await runGenerateBundle(plugin, ctx);
        expect(logger.info).toHaveBeenCalledWith(expect.stringContaining('clean'));
        expect(ctx.emitFile).toHaveBeenCalledWith({
            type: 'asset',
            fileName: path.normalize('cards-npm-audit.json'),
            source,
        });
    });
    it('logs warn when audit finds vulnerabilities (non-zero exit, valid JSON)', async () => {
        const source = JSON.stringify({
            metadata: { vulnerabilities: { total: 3, high: 1 } },
        });
        vi.mocked(runNpmAuditJson).mockResolvedValue({
            source,
            exitCode: 1,
            skipped: false,
        });
        const { logger, plugin } = createPlugin('/tmp/ext');
        const ctx = createRollupContext();
        await runGenerateBundle(plugin, ctx);
        expect(logger.warn).toHaveBeenCalledWith(expect.stringContaining('vulnerabilities'));
        expect(logger.error).not.toHaveBeenCalled();
        expect(ctx.emitFile).toHaveBeenCalledTimes(1);
    });
    it('logs error when audit returns a synthetic error payload', async () => {
        const source = JSON.stringify({
            error: { message: 'npm is not available or not in PATH', code: 'ENOENT' },
        });
        vi.mocked(runNpmAuditJson).mockResolvedValue({
            source,
            exitCode: 127,
            skipped: false,
        });
        const { logger, plugin } = createPlugin('/tmp/ext');
        const ctx = createRollupContext();
        await runGenerateBundle(plugin, ctx);
        expect(logger.error).toHaveBeenCalledWith(expect.stringContaining('failed'));
        expect(logger.warn).not.toHaveBeenCalled();
        expect(ctx.emitFile).toHaveBeenCalledTimes(1);
    });
    it('runs audit only once for the same auditRoot', async () => {
        const source = '{"metadata":{"vulnerabilities":{"total":0}}}';
        vi.mocked(runNpmAuditJson).mockResolvedValue({
            source,
            exitCode: 0,
            skipped: false,
        });
        const root = path.resolve('/tmp/extensions/cards');
        const { plugin: plugin1 } = createPlugin(root, 'ExtA.js');
        const { logger: logger2, plugin: plugin2 } = createPlugin(root, 'ExtB.js');
        const ctx1 = createRollupContext();
        const ctx2 = createRollupContext();
        await runGenerateBundle(plugin1, ctx1);
        await runGenerateBundle(plugin2, ctx2);
        expect(runNpmAuditJson).toHaveBeenCalledTimes(1);
        expect(ctx1.emitFile).toHaveBeenCalledTimes(1);
        expect(ctx2.emitFile).not.toHaveBeenCalled();
        expect(logger2.debug).toHaveBeenCalledWith(expect.stringContaining('already ran'));
    });
    it('runs audit separately for different auditRoots', async () => {
        const source = '{"metadata":{"vulnerabilities":{"total":0}}}';
        vi.mocked(runNpmAuditJson).mockResolvedValue({
            source,
            exitCode: 0,
            skipped: false,
        });
        const { plugin: plugin1 } = createPlugin(path.resolve('/tmp/extensions/cards'));
        const { plugin: plugin2 } = createPlugin(path.resolve('/tmp/extensions/settings'));
        const ctx1 = createRollupContext();
        const ctx2 = createRollupContext();
        await runGenerateBundle(plugin1, ctx1);
        await runGenerateBundle(plugin2, ctx2);
        expect(runNpmAuditJson).toHaveBeenCalledTimes(2);
        expect(ctx1.emitFile).toHaveBeenCalledTimes(1);
        expect(ctx2.emitFile).toHaveBeenCalledTimes(1);
        expect(ctx1.emitFile).toHaveBeenCalledWith(expect.objectContaining({
            fileName: path.normalize('cards-npm-audit.json'),
        }));
        expect(ctx2.emitFile).toHaveBeenCalledWith(expect.objectContaining({
            fileName: path.normalize('settings-npm-audit.json'),
        }));
    });
});
